        for (const p of parts) { p.y += 520 * mv; p.x -= 120 * mv; if (p.y > SCENE_BOT) { p.y = SCENE_TOP; p.x = Math.random() * (W + 60); }
          ctx.moveTo(Math.round(p.x), Math.round(p.y)); ctx.lineTo(Math.round(p.x - 3), Math.round(p.y + 9)); }
