        ctx.fillStyle = `rgba(${g.c},${(g.a * (.6 + .4 * fl)).toFixed(3)})`; ctx.beginPath(); ctx.ellipse(g.x, g.y, g.rx, g.ry, 0, 0, 6.29); ctx.fill();
